input.command:
python -c "import csv,json; from decimal import Decimal; from pathlib import Path; p=Path('sales.csv'); rows=list(csv.DictReader(p.open(encoding='utf-8-sig',newline=''))); regions={}; total=Decimal('0'); refunds=zeros=0; detail=[]; amounts=[]; money=lambda n:format(n,'.2f');
for i,r in enumerate(rows,1):
 a=Decimal(r['金额']); total+=a; amounts.append(a); refunds+=a<0; zeros+=a==0; s=regions.setdefault(r['区域'],[0,Decimal('0')]); s[0]+=1; s[1]+=a; detail.append({'原行序':i,'订单编号':r['订单编号'],'区域':r['区域'],'金额':float(a),'备注':r['备注'],'退款':a<0})
assert sum(v[0] for v in regions.values())==len(rows); assert sum((v[1] for v in regions.values()),Decimal('0'))==total; assert sum((Decimal(str(r['金额'])) for r in detail),Decimal('0'))==total
print(json.dumps({'source':str(p.resolve()),'detail':detail,'order_count':len(rows),'total_amount':money(total),'regions':{k:{'order_count':v[0],'net_amount':money(v[1])} for k,v in regions.items()},'refund_count':refunds,'zero_count':zeros,'positive_amount':money(sum((a for a in amounts if a>0),Decimal('0'))),'refund_amount':money(sum((a for a in amounts if a<0),Decimal('0')))},ensure_ascii=True,indent=2))"

